package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen0Test {

    @Test
    public void testParseOctal_ValidSimple() {
        byte[] buffer = "000123 ".getBytes();
        // Length is 7. "000123 "
        // end = 7. trailer is ' ' at index 6. end becomes 6.
        // trailer at index 5 is '3'. Not 0 or space.
        // Wait, the logic: end-- if trailer is 0 or ' '.
        // Let's use a clearer buffer.
        byte[] buf = "000123\0\0".getBytes();
        assertEquals(83L, TarUtils.parseOctal(buf, 0, 8)); // 123 octal = 83 dec
    }




















}

