    public void testParseOctal_OffsetAndLength() {
        byte[] buf = "junk 0123  junk".getBytes();
        // offset 5, length 7 -> "0123  "
        // start=5, end=12.
        // trailer at 11 is ' '. end becomes 11.
        // trailer at 10 is ' '. end becomes 10.
        // digits: 0, 1, 2, 3.
        assertEquals(10L, TarUtils.parseOctal(buf, 5, 7));
    }






