package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_parseOctal_TriageGen0Test {



















    @Test
    public void testParseOctal_TrailingNULs() {
        byte[] buf = "012\0\0\0".getBytes();
        // end = 7. trailer at 6 is 0. end=6.
        // trailer at 5 is 0. end=5.
        // loop start=0 to 5. digits 0,1,2,\0.
        // Wait, if a NUL is encountered in the loop, it hits the 'currentByte < '0'' check.
        // The code expects digits in the loop.
        // Let's test the specific logic: "May have additional NUL or space"
        byte[] buf2 = "012\0 ".getBytes();
        // end=5. trailer at 4 is ' '. end=4.
        // trailer at 3 is 0. end=3.
        // loop 0 to 3: '0','1','2'.
        assertEquals(10L, TarUtils.parseOctal(buf2, 0, 5));
    }


}

