public class TarUtils_parseOctal_TriageGen0Test {





















    @Test
    public void testParseOctal_LeadingSpacesOnly() {
        // Length must be at least 2.
        // If all are spaces, it's not allNUL (which checks for 0).
        // It will skip spaces. start will equal end. Loop won't run. Result 0.
        byte[] buf = "   ".getBytes();
        assertEquals(0L, TarUtils.parseOctal(buf, 0, 3));
    }
}
